= async (lock) => {
    if (!lock?.key) return;
    await redis.eval(
        `if redis.call("get", KEYS[1]) == ARGV[1] then
            return redis.call("del", KEYS[1])
        end
        return 0`,
        { keys: [lock.key], arguments: [lock.token] }
    );
};

